'use strict';

function selectParcelsByZone(parcels, zone) {
  if (!Array.isArray(parcels)) {
    throw new TypeError('parcels must be an array');
  }
  if (typeof zone !== 'string') {
    throw new TypeError('zone must be a string');
  }

  return parcels.filter((parcel) =>
    parcel !== null &&
    typeof parcel === 'object' &&
    typeof parcel.zone === 'string' &&
    parcel.zone === zone
  );
}

module.exports = { selectParcelsByZone };

