'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api).sort(), ['selectParcelsByZone']);
const { selectParcelsByZone } = api;

const a = { id: 1, zone: 'North' };
const b = { id: 2, zone: 'south' };
const c = { id: 3, zone: 'NORTH' };
const malformed = [null, undefined, 4, 'North', {}, { zone: null }, { zone: 3 }];
const parcels = [a, ...malformed, b, a, c];
const snapshot = parcels.slice();
const result = selectParcelsByZone(parcels, 'north');
assert.deepEqual(result, [a, a, c]);
assert.notStrictEqual(result, parcels);
assert.strictEqual(result[0], a);
assert.strictEqual(result[1], a);
assert.strictEqual(result[2], c);
assert.deepEqual(parcels, snapshot);
assert.equal(a.zone, 'North');
assert.deepEqual(selectParcelsByZone([], 'x'), []);
assert.deepEqual(selectParcelsByZone(parcels, 'missing'), []);
assert.deepEqual(selectParcelsByZone([{ zone: ' north ' }, { zone: 'north' }], ' north '), [{ zone: ' north ' }]);
assert.deepEqual(selectParcelsByZone([{ zone: '' }], ''), [{ zone: '' }]);
for (const bad of [null, undefined, {}, 'x', 1]) {
  assert.throws(() => selectParcelsByZone(bad, 'x'), TypeError);
}
for (const bad of [null, undefined, {}, [], 1]) {
  assert.throws(() => selectParcelsByZone([], bad), TypeError);
}

